def processConfig(self, config):
    import threading
    st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
    # On a restart, remember which forecast nodes already exist so refresh() can remove extras.
    try:
        nodes = (config or {}).get('nodes') or []
        if isinstance(nodes, dict):
            addrs = list(nodes.keys()) + [n.get('address') for n in nodes.values() if isinstance(n, dict)]
        else:
            addrs = [n.get('address') for n in nodes if isinstance(n, dict)]
        st['known'] = set(a for a in addrs if isinstance(a, str) and a.startswith('fcst_'))
    except Exception as ex:
        LOGGER.error('processConfig: %s', type(ex).__name__)

override_bodies.parameterHandler:
def parameterHandler(self, params):
    import threading
    st = self.__dict__.setdefault('_wxs', {'cfg': {}, 'nodes': {}, 'lock': threading.Lock(), 'started': False, 'known': set()})
    params = params or {}
    api_key = str(params.get('api_key') or '').strip()
    location = str(params.get('location') or '').strip()
    units = str(params.get('units') or 'us').strip().lower()
    notes = []
    metric = False
    if units in ('metric', 'si'):
        metric = True
    elif units not in ('us', 'imperial'):
        notes.append("units must be 'us' or 'metric' (you entered '%s'); using 'us'." % units)
    days_raw = str(params.get('forecast_days') or '3').strip()
    try:
        days = int(float(days_raw))
    except ValueError:
        days = 3
        notes.append("forecast_days must be a whole number from 1 to 14 (you entered '%s'); using 3." % days_raw)
    if days < 1 or days > 14:
        days = min(max(days, 1), 14)
        notes.append('forecast_days must be between 1 and 14; using %d.' % days)

    def setn(key, msg):
        try:
            if msg:
                self.poly.Notices[key] = msg
            else:
                self.poly.Notices.delete(key)
        except Exception as ex:
            LOGGER.debug('notice %s: %s', key, type(ex).__name__)

    setn('config', None if (api_key and location) else "Enter your WeatherAPI.com api_key and location in the plugin's Custom Parameters, then save.")
    setn('params', ' '.join(notes) if notes else None)

    new = {'api_key': api_key, 'location': location, 'metric': metric, 'days': days}
    changed = new != st['cfg']
    st['cfg'] = new
    # Settings edited while running: refresh right away (off this thread).
    if st['started'] and changed and api_key and location:
        threading.Thread(target=self.refresh, daemon=True).start()

override_bodies.stop:
def stop(self):
    st = self.__dict__.get('_wxs')
    if st:
        st['started'] = False
    LOGGER.info('WeatherAPI stopped')
